let bookGroup='',bookTab='lesson';
function bookCatalog(){
  const list=textbook.filter(u=>(!bookGroup||u.group===bookGroup)&&(!search||`${u.number} ${u.title} ${u.group}`.toLowerCase().includes(search.toLowerCase())));
  const completed=Object.keys(state.bookCompleted||{}).length;
  return `${heading('KITOBDAGI UNITLAR','100 units. One clear learning path.','English Vocabulary in Use · Pre-intermediate and Intermediate · Fourth edition')}
  <section class="card book-summary"><div><span class="tag">CAMBRIDGE · A2–B1</span><h2>Kitobdagi barcha 100 ta unit</h2><p>Har bir unitning dars va mashq sahifalari asl PDF bilan bog‘langan. ${completed} / 100 unit o‘qib chiqilgan.</p></div><a class="btn secondary" href="textbook.pdf" target="_blank" rel="noopener">Kitobni ochish ${icon('book')}</a></section>
  <div class="study-toolbar"><input id="search" class="search" placeholder="Unit raqami yoki mavzusini qidiring…" aria-label="Search units" value="${esc(search)}"><select id="book-group" aria-label="Filter by topic"><option value="">Barcha mavzular</option>${[...new Set(textbook.map(u=>u.group))].map(g=>`<option value="${esc(g)}" ${bookGroup===g?'selected':''}>${esc(g)}</option>`).join('')}</select><span class="library-count">${list.length} ta unit</span></div>
  <div class="section-grid">${list.map(u=>`<section class="card unit-tile"><div class="card-head"><span class="tag">UNIT ${String(u.number).padStart(2,'0')}</span>${state.bookCompleted?.[u.number]?`<span class="read-status">${icon('check')} O‘qilgan</span>`:''}</div><p class="book-category">${esc(u.group)}</p><h2>${esc(u.title)}</h2><p>Kitob sahifalari: ${u.printedPage}–${u.printedPage+1}<br>Dars · Mashqlar · Asl PDF</p><a class="btn secondary" href="#unit-${u.number}">Unitni ochish ${icon('arrow')}</a></section>`).join('')||'<div class="empty">Mos unit topilmadi.</div>'}</div><p class="hint">Manba: siz yuborgan English Vocabulary in Use PDF kitobi. Interaktiv kartochkalarga hozircha 36 ta boshlang‘ich so‘z kiritilgan.</p>`;
}
function bookLesson(){
  const number=+page.slice(5),u=textbook[number-1];if(!u)return bookCatalog();
  const ws=words.filter(w=>w.unit===number-1);
  return `${heading(`UNIT ${String(number).padStart(2,'0')} · ${esc(u.group)}`,esc(u.title),`English Vocabulary in Use · Kitob sahifalari ${u.printedPage}–${u.printedPage+1}`)}
  <div class="study-toolbar"><a class="text-link" href="#units">← Barcha unitlar</a><div class="mode-tabs" style="margin:0">${[['lesson','Dars'],['exercises','Mashqlar'],['pdf','Asl PDF']].map(([v,label])=>`<button class="btn ${bookTab===v?'':'secondary'}" data-book-tab="${v}">${label}</button>`).join('')}</div><a class="text-link" href="textbook.pdf#page=${u.page+(bookTab==='exercises'?1:0)}" target="_blank" rel="noopener">PDF’da ochish ${icon('arrow')}</a></div>
  ${bookTab==='pdf'?`<iframe class="book-pdf" src="textbook.pdf#page=${u.page}" title="Unit ${number}: ${esc(u.title)}"><p><a href="textbook.pdf#page=${u.page}">PDF’ni ochish</a></p></iframe>`:`<section class="card book-reading"><div class="card-head"><span class="tag">${bookTab==='lesson'?'DARS MATNI':'KITOBDAGI MASHQLAR'}</span><small class="muted">${bookTab==='lesson'?u.printedPage:u.printedPage+1}-sahifa</small></div>${bookTab==='exercises'?'<p class="book-notice">Mashqlarni kitobdagi ko‘rsatmalar bo‘yicha bajaring. Bu sahifadagi javoblar avtomatik tekshirilmaydi.</p>':''}<div class="book-text">${esc(bookTab==='lesson'?u.lesson:u.exercises)}</div><p class="hint">Rasm, jadval va asl sahifa tuzilishini ko‘rish uchun «Asl PDF»ni oching.</p></section>`}
  <section class="card" style="margin-top:20px"><div class="study-toolbar"><strong>${state.bookCompleted?.[number]?'Bu unit o‘qib chiqilgan':'Unitni o‘qib chiqdingizmi?'}</strong><button class="btn ${state.bookCompleted?.[number]?'secondary':''}" id="mark-read">${icon('check')}${state.bookCompleted?.[number]?'Belgini bekor qilish':'O‘qildi deb belgilash'}</button></div><p class="hint" style="text-align:left">O‘qilganlik belgisi so‘zlarni bilish natijalaridan alohida saqlanadi.</p>${ws.length?`<button class="btn secondary" data-unit="${number-1}">${ws.length} ta tayyor so‘z bilan mashq qilish ${icon('cards')}</button>`:'<p class="muted" style="font-size:12px">Ushbu unit so‘zlari hali o‘zbekcha tarjimali interaktiv kartochkalarga aylantirilmagan. Dars va mashqlarni yuqorida o‘qishingiz mumkin.</p>'}</section>
  <div class="study-toolbar" style="margin-top:22px">${number>1?`<a class="btn secondary" href="#unit-${number-1}">← Unit ${number-1}</a>`:'<span></span>'}${number<100?`<a class="btn secondary" href="#unit-${number+1}">Unit ${number+1} →</a>`:''}</div>`;
}
function bindBook(){
  const select=document.getElementById('book-group');if(select)select.onchange=()=>{bookGroup=select.value;render()};
  document.querySelectorAll('[data-book-tab]').forEach(b=>b.onclick=()=>{bookTab=b.dataset.bookTab;render()});
  document.querySelectorAll('[data-open-unit]').forEach(b=>b.onclick=()=>go(`unit-${b.dataset.openUnit}`));
  const mark=document.getElementById('mark-read');if(mark)mark.onclick=()=>{const n=+page.slice(5);state.bookCompleted=state.bookCompleted||{};if(state.bookCompleted[n])delete state.bookCompleted[n];else state.bookCompleted[n]=Date.now();save();render()};
}
